def variable_type(vector, boolean_type="numeric") -> str:
    """Determine whether a vector contains numeric, categorical, or datetime data.

    This function differs from the pandas typing API in a few ways:

    - Python sequences or object-typed PyData objects are considered numeric if
      all of their entries are numeric.
    - String or mixed-type data are considered categorical even if not
      explicitly represented as a :class:`pandas.api.types.CategoricalDtype`.
    - There is some flexibility about whether numerical encodings can be used
      for either categorical or numeric data, depending on the `boolean_type`
      parameter.

    """
    vector = np.asarray(vector)

    # If the vector has the object dtype, it may be a mix of numeric and
    # categorical values, so we need to check the type of each value
    if vector.dtype == "object":
        # Check for datetime
        try:
            vector = pd.to_datetime(vector)
        except (ValueError, TypeError):
            pass
        else:
            return "datetime"
        # Check for numeric
        try:
            vector = np.asarray(vector, float)
        except (ValueError, TypeError):
            pass
        else:
            return "numeric"
        # Otherwise, it's categorical
        return "categorical"

    # If the data is numeric or boolean, return numeric
    if np.issubdtype(vector.dtype, np.number):
        return "numeric"
    elif vector.dtype == bool:
        return boolean_type

    # If the data is datetime, return datetime
    elif np.issubdtype(vector.dtype, np.datetime64):
        return "datetime"

    # Otherwise, it's categorical
    else:
        return "categorical"
