    boolean_type : 'numeric' or 'categorical'
        Type to return for boolean data.

    Returns
    -------
    type : {'numeric', 'categorical', 'datetime'}
        The resulting type.

    """
    vector = pd.Series(vector)

    # Special-case all-na data, which is always "numeric"
    if pd.isna(vector).all():
        return "numeric"

    # Special-case binary/boolean data, allow caller to determine
    if pd.api.types.is_bool_dtype(vector):
        return boolean_type

    # Now we can proceed with the rest of the checks
    if pd.api.types.is_numeric_dtype(vector):
        return "numeric"
    elif pd.api.types.is_datetime64_dtype(vector):
        return "datetime"
    elif pd.api.types.is_categorical_dtype(vector):
        return "categorical"
    else:
        # We have a string type, but it may be numeric-like
        try:
            with np.errstate(invalid="ignore"):
                vector = vector.astype(float)
        except (ValueError, TypeError):
            return "categorical"
        else:
            return "numeric"
